// Replace the trigger with your source (Typeform, Webflow, Gmail, CRM…) and map its fields below.
// Self-hosted n8n: allow the crypto module with NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');

// Paste your workspace webhook secret (LeadPilot → Settings → Webhook secret).
// Better: store it in an n8n credential/variable instead of hardcoding it here.
const SECRET = 'REPLACE_WITH_WEBHOOK_SECRET';

return $input.all().map((item, i) => {
  const src = item.json;
  const lead = {
    // Stable id from your source system => n8n retries never create duplicate leads.
    external_id: String(src.id ?? `n8n-${$execution.id}-${i}`),
    name: src.name ?? 'Maya Chen',
    email: src.email ?? 'maya@brightpath.example',
    company: src.company ?? 'BrightPath Logistics',
    message: src.message ?? 'We re-key ~300 shipment requests a week into our TMS and want an AI agent for it. Budget ~$18k, start next month.',
    source: 'n8n',
  };
  // Sign the exact string we send: HMAC-SHA256(secret, `${timestamp}.${body}`).
  const body = JSON.stringify(lead);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto.createHmac('sha256', SECRET).update(`${timestamp}.${body}`).digest('hex');
  return { json: { body, timestamp, signature } };
});
